import heapq
import sys
from functools import lru_cache


class Solution:
    def countRestrictedPaths(self, n: int, edges: List[List[int]]) -> int:
        adj = [[] for _ in range(n + 1)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        dist = [float('inf')] * (n + 1)
        dist[n] = 0
        heap = [(0, n)]
        while heap:
            d, x = heapq.heappop(heap)
            if d > dist[x]:
                continue
            for y, w in adj[x]:
                if d + w < dist[y]:
                    dist[y] = d + w
                    heapq.heappush(heap, (dist[y], y))

        sys.setrecursionlimit(2 * n + 10)

        @lru_cache(maxsize=None)
        def dfs(x):
            if x == n:
                return 1
            total = 0
            for y, _ in adj[x]:
                if dist[y] < dist[x]:
                    total += dfs(y)
            return total % 1000000007

        return dfs(1)

